INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1000001, 3.414, 1, "2025/01/31 12:00:00", 1, "2030/01/01 14:59:59", 190801, "カリン", 0, -416.5, 1, 62, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1000002, 3.099, 1, "2025/01/31 12:00:00", 2, "2030/01/01 14:59:59", 190801, "カリン", 0, -416.5, 1, 62, "ミッションをクリアして、\n報酬をゲットしましょう！", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1000003, 2.801, 1, "2025/01/31 12:00:00", 3, "2030/01/01 14:59:59", 190801, "カリン", 0, -416.5, 1, 63, "受け取ることができる\n報酬があるようです\n確認してみてください", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1000004, 0, 1, "2025/01/31 12:00:00", 4, "2030/01/01 14:59:59", 190801, "カリン", 0, -416.5, 2, 63, "報酬がもらえますよ！\nチェックしてみてください", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1000005, 2.12, 1, "2025/01/31 12:00:00", 5, "2030/01/01 14:59:59", 190801, "カリン", 0, -363, 2, 64, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1000006, 1.68, 1, "2025/01/31 12:00:00", 6, "2030/01/01 14:59:59", 190801, "カリン", 0, -363, 1, 64, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1000007, 2.33, 1, "2025/01/31 12:00:00", 7, "2030/01/01 14:59:59", 190801, "カリン", 0, -363, 2, 64, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1020101, 5.18, 10201, "2025/01/31 12:00:00", 101, "2030/01/01 14:59:59", 133701, "ラビリスタ", -6, -285, 3, 61, "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", 7);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1020102, 8.77, 10201, "2025/01/31 12:00:00", 201, "2030/01/01 14:59:59", 133901, "クリスティーナ", -2, -285, 1, 61, "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1020103, 15.5, 10201, "2025/01/31 12:00:00", 301, "2030/01/01 14:59:59", 133801, "ネネカ", 0, -285, 6, 61, "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1020201, 9.061, 10202, "2025/02/28 12:00:00", 101, "2030/01/01 14:59:59", 134301, "ランファ", 0, -285, 2, 61, "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", 5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1020202, 7.699, 10202, "2025/02/28 12:00:00", 201, "2030/01/01 14:59:59", 134401, "チカ", 0, -285, 1, 61, "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1020301, 8.595, 10203, "2025/03/31 12:00:00", 101, "2030/01/01 14:59:59", 134601, "アオイ", 0, -285, 1, 61, "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1020302, 7.758, 10203, "2025/03/31 12:00:00", 201, "2030/01/01 14:59:59", 134501, "クローチェ", 0, -285, 1, 61, "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1020401, 7, 10204, "2025/04/30 12:00:00", 101, "2030/01/01 14:59:59", 132302, "ルイズマリー", 0, -285, 2, 61, "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", 6);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1020402, 7.904, 10204, "2025/04/30 12:00:00", 201, "2030/01/01 14:59:59", 132402, "イロハ", 0, -285, 1, 61, "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1020403, 8.487, 10204, "2025/04/30 12:00:00", 301, "2030/01/01 14:59:59", 132502, "ソノ", 0, -285, 4, 61, "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1020502, 8.763, 10205, "2025/05/31 12:00:00", 101, "2030/01/01 14:59:59", 134901, "カノン", 0, -285, 1, 61, "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1020503, 6.417, 10205, "2025/05/31 12:00:00", 201, "2030/01/01 14:59:59", 134801, "ツムギ", 0, -285, 1, 61, "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1020601, 10.335, 10206, "2025/06/30 12:00:00", 101, "2030/01/01 14:59:59", 135001, "エリス", 0, -285, 3, 61, "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", 7);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1020602, 6.281, 10206, "2025/06/30 12:00:00", 201, "2030/01/01 14:59:59", 135101, "シェフィ", 0, -285, 2, 61, "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", 4);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1020603, 12.244, 10206, "2025/06/30 12:00:00", 301, "2030/01/01 14:59:59", 135201, "プレシア", 0, -285, 1, 61, "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1020701, 6.339, 10207, "2025/07/31 12:00:00", 101, "2030/01/01 14:59:59", 135301, "クリア", 0, -285, 2, 61, "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", 8);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1020702, 8.184, 10207, "2025/07/31 12:00:00", 201, "2030/01/01 14:59:59", 135401, "アネモネ", 0, -285, 7, 61, "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", 9);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1020801, 3.906, 10208, "2025/08/31 12:00:00", 101, "2030/01/01 14:59:59", 129101, "アイラ", 0, -285, 9, 61, "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1020802, 14.465, 10208, "2025/08/31 12:00:00", 201, "2030/01/01 14:59:59", 129201, "シナツ", 0, -285, 1, 61, "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1020803, 8.662, 10208, "2025/08/31 12:00:00", 301, "2030/01/01 14:59:59", 100101, "ヒヨリ", 0, -285, 4, 61, "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1020804, 10.915, 10208, "2025/08/31 12:00:00", 401, "2030/01/01 14:59:59", 100301, "レイ", 0, -285, 1, 61, "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1020901, 6.042, 10209, "2025/09/30 12:00:00", 101, "2030/01/01 14:59:59", 135802, "ユキノ", 0, -285, 1, 61, "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", 7);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1020902, 9.402, 10209, "2025/09/30 12:00:00", 201, "2030/01/01 14:59:59", 135903, "サツキ", 0, -285, 4, 61, "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1020903, 8.16, 10209, "2025/09/30 12:00:00", 301, "2030/01/01 14:59:59", 136902, "ルルィ", 0, -285, 8, 61, "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021001, 5, 10210, "2025/10/31 12:00:00", 101, "2030/01/01 14:59:59", 137401, "カスミ", 0, -285, 3, 61, "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021002, 8.12, 10210, "2025/10/31 12:00:00", 201, "2030/01/01 14:59:59", 136001, "アラクネ", 0, -285, 4, 61, "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021003, 6.386, 10210, "2025/10/31 12:00:00", 301, "2030/01/01 14:59:59", 136202, "ナーナ", 0, -285, 4, 61, "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021101, 7.438, 10211, "2025/11/30 12:00:00", 101, "2030/01/01 14:59:59", 136402, "ユイ", 0, -285, 3, 61, "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", 4);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021102, 8.35, 10211, "2025/11/30 12:00:00", 201, "2030/01/01 14:59:59", 136302, "ミソラ", 0, -285, 1, 61, "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", 5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021201, 5, 10212, "2025/12/31 12:00:00", 101, "2030/01/01 14:59:59", 136501, "シズル", 0, -285, 1, 61, "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021202, 5.25, 10212, "2025/12/31 12:00:00", 201, "2030/01/01 14:59:59", 137902, "リノ", 0, -285, 1, 61, "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021203, 7.5, 10212, "2025/12/31 12:00:00", 301, "2030/01/01 14:59:59", 106801, "ラビリスタ", 0, -285, 1, 61, "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021301, 8.204, 10213, "2026/01/31 12:00:00", 101, "2030/01/01 14:59:59", 126501, "ライラエル", 0, -285, 1, 61, "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021302, 7.176, 10213, "2026/01/31 12:00:00", 201, "2030/01/01 14:59:59", 129701, "ネフィ＝ネラ", 0, -285, 1, 61, "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021303, 8.602, 10213, "2026/01/31 12:00:00", 301, "2030/01/01 14:59:59", 133101, "ヴァイオレット", 0, -285, 1, 61, "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", 5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021304, 10.14, 10213, "2026/02/06 12:00:00", 102, "2030/01/01 14:59:59", 138101, "ライラエル", 0, -285, 1, 61, "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021305, 10.152, 10213, "2026/02/06 12:00:00", 202, "2030/01/01 14:59:59", 138201, "ネフィ＝ネラ", 0, -285, 1, 61, "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", 7);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021306, 9.688, 10213, "2026/02/06 12:00:00", 302, "2030/01/01 14:59:59", 138001, "ヴァイオレット", 0, -285, 4, 61, "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021307, 5.928, 10213, "2026/02/12 12:00:00", 401, "2030/01/01 14:59:59", 138301, "ペコリーヌ", 0, -285, 2, 61, "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021401, 9.19, 10214, "2026/02/28 12:00:00", 101, "2030/01/01 14:59:59", 138702, "ワカナ", 0, -285, 4, 61, "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021402, 8.724, 10214, "2026/02/28 12:00:00", 201, "2030/01/01 14:59:59", 138802, "シオリ", 0, -285, 1, 61, "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021501, 7.758, 10215, "2026/03/31 12:00:00", 101, "2030/01/01 14:59:59", 138902, "グレイス", 0, -285, 4, 61, "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021502, 6.375, 10215, "2026/03/31 12:00:00", 201, "2030/01/01 14:59:59", 139002, "キョウカ", 0, -285, 6, 61, "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", 4);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021503, 6.173, 10215, "2026/03/31 12:00:00", 301, "2030/01/01 14:59:59", 136902, "ルルィ", 0, -285, 6, 61, "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021601, 4.202, 10216, "2026/04/30 12:00:00", 101, "2030/01/01 14:59:59", 139202, "ミホ", 0, -285, 6, 61, "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021602, 2.842, 10216, "2026/04/30 12:00:00", 201, "2030/01/01 14:59:59", 139302, "マホ", 0, -285, 6, 61, "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021603, 4.598, 10216, "2026/04/30 12:00:00", 301, "2030/01/01 14:59:59", 139402, "エリカ", 0, -285, 4, 61, "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021701, 6.533, 10217, "2026/05/31 12:00:00", 101, "2030/01/01 14:59:59", 125802, "リリ", 0, -285, 4, 61, "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021702, 5, 10217, "2026/05/31 12:00:00", 301, "2030/01/01 14:59:59", 126102, "プレシア", 0, -285, 3, 61, "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021703, 5.214, 10217, "2026/05/31 12:00:00", 201, "2030/01/01 14:59:59", 126002, "クリア", 0, -285, 3, 61, "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", 4);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021704, 8.781, 10217, "2026/05/31 12:00:00", 102, "2030/01/01 14:59:59", 139501, "リリ", 0, -285, 1, 61, "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021705, 6.529, 10217, "2026/05/31 12:00:00", 202, "2030/01/01 14:59:59", 139601, "クリア", 0, -285, 2, 61, "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021706, 3.195, 10217, "2026/05/31 12:00:00", 302, "2030/01/01 14:59:59", 139701, "プレシア", 0, -285, 3, 61, "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021801, 12.43, 10218, "2026/06/30 12:00:00", 101, "2030/01/01 14:59:59", 139902, "ルイズマリー", 0, -285, 2, 61, "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021802, 6.35, 10218, "2026/06/30 12:00:00", 201, "2030/01/01 14:59:59", 140001, "クレジッタ", 0, -285, 2, 61, "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021901, 10.23, 10219, "2026/07/31 12:00:00", 101, "2030/01/01 14:59:59", 140102, "フブキ", 0, -285, 1, 61, "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", 5);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1021902, 5.584, 10219, "2026/07/31 12:00:00", 201, "2030/01/01 14:59:59", 140201, "ヴァンピィ", 0, -285, 1, 61, "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1022001, 2.8, 10220, "2026/08/31 12:00:00", 201, "2030/01/01 14:59:59", 126401, "クローチェ", 0, -285, 6, 61, "あっちもこっちも、\nエマージェンシーですっ！\nみんなのピンチを助けるために\n行きましょうっ、ナイトさんっ！", 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1022002, 8.9, 10220, "2026/08/31 12:00:00", 101, "2030/01/01 14:59:59", 127802, "ヴルム", 0, -285, 4, 61, "みんながあたしを許してくれても…\nあたしは、あたしを許せない\nそれでも…この世界が危ないなら\n迷ってなんか、いられない", 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1022003, 4.49, 10220, "2026/08/31 12:00:00", 202, "2030/01/01 14:59:59", 140602, "クローチェ", 0, -285, 2, 61, "クローチェ、サブマリンモードっ\n換装完了ですっ♪\nどんな荒波も、ナイトさんとなら\n越えちゃいますからっ！", 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1022004, 9.42, 10220, "2026/08/31 12:00:00", 102, "2030/01/01 14:59:59", 140501, "ヴルム", 0, -285, 1, 61, "偽物でも、創り物でもいい\nあたしの中にある気持ちは、\nあたしの本物だから\n今度こそ、この力で守ってみせる", 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1022005, 7, 10220, "2026/08/31 12:00:00", 301, "2030/01/01 14:59:59", 140402, "リーザ", 0, -285, 4, 61, "世界と向き合うなんてこと…\n私には、わからない\nそれでも、受けた借りは\nちゃんと返さないとね", 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1022101, 8.61, 10221, "2026/10/31 12:00:00", 101, "2030/01/01 14:59:59", 141101, "アーモンドアイ", 0, -285, 1, 61, "ゲームの世界、ね\n分からないことばかりだけれど\nやることは変わらないわ\nどんな場所でもわたしは負けない！", 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1022102, 3.55, 10221, "2026/10/31 12:00:00", 201, "2030/01/01 14:59:59", 141201, "ラッキーライラック", 0, -285, 6, 61, "ゴルシさんは相変わらずやねぇ…\nまぁせっかくの異世界やし\nいつもと違うレース、\n楽しませてもらいましょ", 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1022103, 8.26, 10221, "2026/10/31 12:00:00", 301, "2030/01/01 14:59:59", 141301, "デアリングタクト", 0, -285, 2, 61, "なんて美しい世界でしょう…！\n現実では見られない景色ばかり\nぜひ一度、この世界の大自然を\n隅から隅まで駆け抜けてみたいです", 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1022104, 8.79, 10221, "2026/10/31 12:00:00", 401, "2030/01/01 14:59:59", 141001, "ゴールドシップ", 0, -285, 2, 61, "来ったぞ～来ったぞ～\nアストルム～っと！\nな～んか平和そうな世界だな\nちょっくら盛り上げてくっか！", 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1022105, 8.61, 10221, "2026/10/31 12:00:00", 101, "2030/01/01 14:59:59", 141101, "アーモンドアイ", 0, -285, 1, 61, "ゲームの世界、ね\n分からないことばかりだけれど\nやることは変わらないわ\nどんな場所でもわたしは負けない！", 3);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1022106, 2.69, 10221, "2026/10/31 12:00:00", 202, "2030/01/01 14:59:59", 141201, "ラッキーライラック", 0, -285, 1, 61, "（剣と魔法！　ええなぁ～！\nうちも魔法覚えられるやろか\nレースの後に花咲かせたり…\nくぅ～っ！　はよ試したいわ！）", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1022107, 8.26, 10221, "2026/10/31 12:00:00", 301, "2030/01/01 14:59:59", 141301, "デアリングタクト", 0, -285, 2, 61, "なんて美しい世界でしょう…！\n現実では見られない景色ばかり\nぜひ一度、この世界の大自然を\n隅から隅まで駆け抜けてみたいです", 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (1022108, 8.79, 10221, "2026/10/31 12:00:00", 401, "2030/01/01 14:59:59", 141001, "ゴールドシップ", 0, -285, 2, 61, "来ったぞ～来ったぞ～\nアストルム～っと！\nな～んか平和そうな世界だな\nちょっくら盛り上げてくっか！", 1);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2000001, 3.414, 2, "2026/04/10 12:00:00", 1, "2030/01/01 14:59:59", 190805, "カリン", 0, -416.5, 1, 62, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 2);
