INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2000003, 2.801, 2, "2026/04/10 12:00:00", 3, "2030/01/01 14:59:59", 190805, "カリン", 0, -416.5, 1, 63, "受け取ることができる\n報酬があるようです\n確認してみてください", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2000004, 0, 2, "2026/04/10 12:00:00", 4, "2030/01/01 14:59:59", 190805, "カリン", 0, -416.5, 2, 63, "報酬がもらえますよ！\nチェックしてみてください", 2);
INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2000005, 2.12, 2, "2026/04/10 12:00:00", 5, "2030/01/01 14:59:59", 190805, "カリン", 0, -363, 2, 64, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 1);
