INSERT INTO `v1_027c6ac2143517fd80aa19d4c65b64120e8a16734186e9b0147300291072a133` VALUES (2000007, 2.33, 2, "2026/04/10 12:00:00", 7, "2030/01/01 14:59:59", 190805, "カリン", 0, -363, 2, 64, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 1);
